      "requirementImplementations": [],
      "dataLeavesInfrastructure": null,
      "dataResidencyCommitment": "",
      "dpaNotes": "",
      "vendorSLA": "",
      "authenticationModel": "",
      "incidentNotificationProcess": "",
      "owner": {},
      "definitionOwner": {},
      "provider": {},
      "authority": {
        "name": "DRAFT Framework",
        "shortName": "DRAFT",
        "source": "DRAFT Framework"
      },
      "shape": "barrel",
      "color": "#7c3a6b",
