      "detail": "{\n  \"schemaVersion\": \"1.0\",\n  \"uid\": \"01KSF4NHSP-8HPP\",\n  \"type\": \"requirement_group\",\n  \"name\": \"Engineering Quality RequirementGroup\",\n  \"description\": \"Optional checklist for ProductComponents covering build quality, test coverage, and performance validation practices. Activated per workspace; does not fire automatically.\",\n  \"version\": \"1.0.0\",\n  \"catalogStatus\": \"complete\",\n  \"authority\": {\n    \"name\": \"DRAFT Framework\",\n    \"shortName\": \"DRAFT\",\n    \"source\": \"DRAFT Framework\"\n  },\n  \"activation\": \"workspace\",\n  \"appliesTo\": [\n    \"product_component\"\n  ],\n  \"requirements\": [\n    {\n      \"id\": \"performance-testing\",\n      \"description\": \"The ProductComponent may declare how performance and load testing is performed.\",\n      \"rationale\": \"Components without a performance testing approach may cause latency or throughput regressions that are not detected before production.\",\n      \"canBeSatisfiedBy\": [\n        {\n          \"mechanism\": \"relationship\",\n          \"criteria\": {\n            \"capability\": \"01KQQ4Q026-S5J6\"\n          },\n          \"example\": \"A load testing platform or service referenced via a relationship object.\"\n        },\n        {\n          \"mechanism\": \"decisionRecord\",\n          \"key\": \"performanceTesting\",\n          \"example\": \"A committed DecisionRecord, referenced from decisionRecords with key: performanceTesting, recording this decision (or why it is not applicable).\"\n        }\n      ],\n      \"minimumSatisfactions\": 1,\n      \"relatedCapability\": \"01KQQ4Q026-S5J6\",\n      \"requirementMode\": \"mandatory\",\n      \"naAllowed\": true,\n      \"validAnswerTypes\": [\n        \"decisionRecord\",\n        \"relationship\"\n      ]\n    },\n    {\n      \"id\": \"quality-gates\",\n      \"description\": \"The ProductComponent may declare the quality gates that govern release readiness.\",\n      \"rationale\": \"Quality gates enforce that code coverage, static analysis, and security scanning thresholds are met before a component can be promoted.\",\n      \"canBeSatisfiedBy\": [\n        {\n          \"mechanism\": \"relationship\",\n          \"criteria\": {\n            \"capability\": \"01KQQ4Q026-RTWC\"\n          },\n          \"example\": \"A CI/CD platform or quality gate service referenced via a relationship object.\"\n        },\n        {\n          \"mechanism\": \"decisionRecord\",\n          \"key\": \"qualityGates\",\n          \"example\": \"A committed DecisionRecord, referenced from decisionRecords with key: qualityGates, recording this decision (or why it is not applicable).\"\n        }\n      ],\n      \"minimumSatisfactions\": 1,\n      \"relatedCapability\": \"01KQQ4Q026-RTWC\",\n      \"requirementMode\": \"mandatory\",\n      \"naAllowed\": true,\n      \"validAnswerTypes\": [\n        \"decisionRecord\",\n        \"relationship\"\n      ]\n    },\n    {\n      \"id\": \"test-authoring\",\n      \"description\": \"The ProductComponent may declare how automated tests are authored and maintained.\",\n      \"rationale\": \"Components with no documented test authoring approach accumulate untested behavior that blocks safe refactoring.\",\n      \"canBeSatisfiedBy\": [\n        {\n          \"mechanism\": \"relationship\",\n          \"criteria\": {\n            \"capability\": \"01KQQ4Q026-QC9S\"\n          },\n          \"example\": \"A test management or specification platform referenced via a relationship object.\"\n        },\n        {\n          \"mechanism\": \"decisionRecord\",\n          \"key\": \"testAuthoring\",\n          \"example\": \"A committed DecisionRecord, referenced from decisionRecords with key: testAuthoring, recording this decision (or why it is not applicable).\"\n        }\n      ],\n      \"minimumSatisfactions\": 1,\n      \"relatedCapability\": \"01KQQ4Q026-QC9S\",\n      \"requirementMode\": \"mandatory\",\n      \"naAllowed\": true,\n      \"validAnswerTypes\": [\n        \"decisionRecord\",\n        \"relationship\"\n      ]\n    },\n    {\n      \"id\": \"test-execution\",\n      \"description\": \"The ProductComponent may declare how automated tests are executed in CI and pre-production environments.\",\n      \"rationale\": \"Test execution infrastructure determines whether test suites run reliably and at sufficient coverage depth during each build or deploy cycle.\",\n      \"canBeSatisfiedBy\": [\n        {\n          \"mechanism\": \"relationship\",\n          \"criteria\": {\n            \"capability\": \"01KQQ4Q026-58Q3\"\n          },\n          \"example\": \"A CI platform or test execution service referenced via a relationship object.\"\n        },\n        {\n          \"mechanism\": \"decisionRecord\",\n          \"key\": \"testExecution\",\n          \"example\": \"A committed DecisionRecord, referenced from decisionRecords with key: testExecution, recording this decision (or why it is not applicable).\"\n        }\n      ],\n      \"minimumSatisfactions\": 1,\n      \"relatedCapability\": \"01KQQ4Q026-58Q3\",\n      \"requirementMode\": \"mandatory\",\n      \"naAllowed\": true,\n      \"validAnswerTypes\": [\n        \"decisionRecord\",\n        \"relationship\"\n      ]\n    }\n  ],\n  \"lifecycleStatus\": \"candidate\",\n  \"tags\": [\n    \"product-component\",\n    \"requirement-group\",\n    \"engineering\",\n    \"quality\",\n    \"optional\"\n  ],\n  \"_source\": \"framework/configurations/requirement-groups/requirement-group-engineering-quality.yaml\"\n}",
