      "internalComponents": [],
      "notes": {
        "patternRationale": "The three-tier pattern separates traffic control, application logic, and data persistence so that each tier can be governed, scaled, and secured independently. The presentation tier is the only tier with direct internet exposure.",
        "presentationTierRequirement": "A NetworkService is required in the presentation tier for all externally-facing deployments. The Draftsman should surface the company-approved WAF or load balancer catalog object when drafting an SDP that follows this pattern.",
        "dataTierIsolation": "Data tier services must not accept direct connections from the presentation tier. All data access flows through the application tier. This constraint will be enforceable via RA constraints when that feature is available."
      },
      "requirements": [],
      "implementations": [],
      "appliesTo": {},
      "inherits": "",
      "scalingUnits": [],
      "networkZones": [],
      "sdpConnections": [],
      "serviceGroups": [
        {
          "name": "Presentation Tier",
          "deployableObjects": [
            {
              "slot": "edge-protection",
              "capability": "01KT0V5MCV-Z079",
              "objectType": "network_service",
              "diagramTier": "presentation",
              "notes": "Traffic inspection and protection service (WAF, application delivery controller, or equivalent). Provides DDoS mitigation, rate limiting, and request filtering before traffic reaches the application tier. The company catalog defines which NetworkService objects satisfy this role."
            },
            {
              "slot": "traffic-management",
              "capability": "01KSWVZSZ5-M0FR",
              "objectType": "network_service",
              "diagramTier": "presentation",
              "notes": "Load balancer distributing stateless traffic across application tier instances. May be combined with the WAF/ADC in a single NetworkService depending on the chosen platform."
            }
          ]
        },
        {
          "name": "Application Tier",
          "deployableObjects": [
            {
              "slot": "application-runtime",
              "capability": "01KT0V5MCV-RZV0",
              "objectType": "runtime_service",
              "diagramTier": "application",
              "notes": "Primary application runtime. Stateless; may be replicated across availability zones. ProductComponents are deployed onto this service."
            }
          ]
        },
        {
          "name": "Data Tier",
          "deployableObjects": [
            {
              "slot": "persistent-data-store",
              "capability": "01KT0V5MCV-VD0Y",
              "objectType": "data_store_service",
              "diagramTier": "data",
              "notes": "Primary persistent data store. Must document backup strategy, RTO, and RPO. DataComponents are deployed onto this service."
            }
          ]
        }
      ],
