      "shape": "round-rectangle",
      "color": "#1f8a5b",
      "source": "catalog/governance/decision-records/dr-aws-agent-factory-network.yaml",
      "tags": [
        "agent-factory",
        "aws",
        "submind",
        "network",
        "edge",
        "cloudflare"
      ],
      "ardCategory": "decision",
      "internalComponents": [],
      "notes": {},
      "requirements": [],
      "implementations": [],
      "appliesTo": {},
      "inherits": "",
      "scalingUnits": [],
      "networkZones": [],
      "sdpConnections": [],
      "serviceGroups": [],
