      "color": "#1f8a5b",
      "source": "catalog/governance/decision-records/dr-aws-agent-factory-recovery.yaml",
      "tags": [
        "agent-factory",
        "aws",
        "submind",
        "availability",
        "backup",
        "recovery"
      ],
      "ardCategory": "decision",
      "internalComponents": [],
      "notes": {},
      "requirements": [],
      "implementations": [],
      "appliesTo": {},
      "inherits": "",
      "scalingUnits": [],
